// Embeds ../Web/index.html (the same player the plugin serves on the local network) into the Worker.
import { readFileSync, writeFileSync } from "node:fs";
const html = readFileSync(new URL("../Web/index.html", import.meta.url), "utf8");
writeFileSync(new URL("./src/page.js", import.meta.url),
  "// Generated by build-page.mjs from Web/index.html — do not edit.\nexport const PAGE_HTML = " + JSON.stringify(html) + ";\n");
console.log("page.js written (" + html.length + " bytes)");
